const MAX_I128 = (1n << 127n) - 1n;

function checkDecimals(decimals: number): void {
  if (!Number.isInteger(decimals) || decimals < 0 || decimals > 38) {
    throw new RangeError("decimals must be an integer from 0 to 38");
  }
}

/** Convert a nonnegative decimal string to exact Soroban token units. No rounding. */
export function parseAmount(value: string, decimals = 7): bigint {
  checkDecimals(decimals);
  if (typeof value !== "string" || !/^(0|[1-9][0-9]*)(\.[0-9]+)?$/.test(value)) {
    throw new TypeError("amount must be a nonnegative decimal string without exponent notation");
  }
  const [whole, fraction = ""] = value.split(".");
  if (fraction.length > decimals) throw new RangeError("amount exceeds token precision");
  const units = BigInt(whole!) * 10n ** BigInt(decimals) + BigInt(fraction.padEnd(decimals, "0") || "0");
  if (units > MAX_I128) throw new RangeError("amount exceeds i128");
  return units;
}

/** Format token units without passing through JavaScript floating-point numbers. */
export function formatAmount(units: bigint, decimals = 7): string {
  checkDecimals(decimals);
  if (typeof units !== "bigint" || units < 0n || units > MAX_I128) throw new RangeError("units must be a nonnegative i128 bigint");
  if (!decimals) return units.toString();
  const digits = units.toString().padStart(decimals + 1, "0");
  const fraction = digits.slice(-decimals).replace(/0+$/, "");
  return digits.slice(0, -decimals) + (fraction ? `.${fraction}` : "");
}

/** Calculate a basis-point fee with the contract's integer rounding toward zero. */
export function calculateFee(amount: bigint, basisPoints: number): bigint {
  if (typeof amount !== "bigint" || amount < 0n || amount > MAX_I128) throw new RangeError("amount must be a nonnegative i128 bigint");
  if (!Number.isInteger(basisPoints) || basisPoints < 0 || basisPoints > 10_000) throw new RangeError("basisPoints must be from 0 to 10000");
  const product = amount * BigInt(basisPoints);
  // The pinned Rust implementation checks multiplication before division.
  if (product > MAX_I128) throw new RangeError("fee multiplication exceeds i128");
  return product / 10_000n;
}

import { Address, nativeToScVal, xdr } from "@stellar/stellar-sdk";
import type { ClaimCheck } from "./contracts/fuul-manager/index.js";
import { validateAddress, validateContractId, validateUnsignedBigInt } from "./validation.js";

/** A complete authorization tree selected by the application before simulation. */
export interface ExpectedAuthorization {
  address: string;
  /** Base64 XDR of SorobanAuthorizedInvocation, including all child invocations. */
  invocation: string;
}

/** Native fee consent for the whole claim batch, selected from trusted application configuration. */
export interface NativeClaimFee {
  asset: string;
  collector: string;
  amount: bigint;
}

/** Build signer intent from local claim data. Project provenance remains the caller's responsibility. */
export function claimAuthorizations(manager: string, checks: readonly ClaimCheck[], caller?: { address: string; nativeFee: NativeClaimFee }): ExpectedAuthorization[] {
  validateContractId(manager, "manager");
  const fieldsFor = (check: ClaimCheck): Record<string, xdr.ScVal> => ({
    amount: nativeToScVal(check.amount, { type: "i128" }),
    currency: new Address(check.currency).toScVal(),
    deadline: nativeToScVal(check.deadline, { type: "u256" }),
    project_address: new Address(check.project_address).toScVal(),
    proof: nativeToScVal(check.proof),
    reason: xdr.ScVal.scvVec([xdr.ScVal.scvSymbol(check.reason.tag)]),
    to: new Address(check.to).toScVal(),
    token_id: nativeToScVal(check.token_id, { type: "u256" }),
  });
  const map = (fields: Record<string, xdr.ScVal>) => xdr.ScVal.scvMap(Object.keys(fields).sort().map(name =>
    new xdr.ScMapEntry({ key: xdr.ScVal.scvSymbol(name), val: fields[name]! })));
  const expected = checks.flatMap(check => {
    const value = map(fieldsFor(check));
    const invocation = new xdr.SorobanAuthorizedInvocation({
      function: xdr.SorobanAuthorizedFunction.sorobanAuthorizedFunctionTypeContractFn(new xdr.InvokeContractArgs({
        contractAddress: new Address(manager).toScAddress(), functionName: "claim", args: [value],
      })),
      subInvocations: [],
    }).toXdr("base64");
    return check.signers.map(address => { validateAddress(address, "claim signer"); return { address, invocation }; });
  });
  if (caller) {
    validateAddress(caller.address, "caller");
    validateContractId(caller.nativeFee.asset, "native fee asset");
    validateAddress(caller.nativeFee.collector, "native fee collector");
    validateUnsignedBigInt(caller.nativeFee.amount, (1n << 127n) - 1n, "native fee amount");
    const call = (contract: string, method: string, args: xdr.ScVal[], subInvocations: xdr.SorobanAuthorizedInvocation[] = []) =>
      new xdr.SorobanAuthorizedInvocation({ function: xdr.SorobanAuthorizedFunction.sorobanAuthorizedFunctionTypeContractFn(
        new xdr.InvokeContractArgs({ contractAddress: new Address(contract).toScAddress(), functionName: method, args })), subInvocations });
    const child = caller.nativeFee.amount === 0n ? [] : [call(caller.nativeFee.asset, "transfer", [
      new Address(caller.address).toScVal(), new Address(caller.nativeFee.collector).toScVal(), nativeToScVal(caller.nativeFee.amount, { type: "i128" }),
    ])];
    const values = checks.map(check => map({ ...fieldsFor(check),
      currency_type: xdr.ScVal.scvVec([xdr.ScVal.scvSymbol(check.currency_type.tag)]),
      signers: xdr.ScVal.scvVec(check.signers.map(address => new Address(address).toScVal())),
    }));
    expected.push({ address: caller.address, invocation: call(manager, "claim", [new Address(caller.address).toScVal(), xdr.ScVal.scvVec(values)], child).toXdr("base64") });
  }
  return expected;
}

import { Buffer } from "buffer";

import { validateBytes } from "./validation.js";

export type Bytes32Input = Uint8Array | `0x${string}`;

const HEX_32_PATTERN = /^0x[0-9a-fA-F]{64}$/;

export function toBytes32(value: Bytes32Input, label = "value"): Buffer {
  if (typeof value !== "string") {
    validateBytes(value, label);
  }
  const bytes =
    typeof value === "string"
      ? HEX_32_PATTERN.test(value)
        ? Buffer.from(value.slice(2), "hex")
        : undefined
      : Buffer.from(value);

  if (bytes === undefined || bytes.length !== 32) {
    throw new TypeError(`${label} must be exactly 32 bytes`);
  }

  return Buffer.from(bytes);
}

export function bytesToHex(value: Uint8Array): `0x${string}` {
  validateBytes(value, "value");
  return `0x${Buffer.from(value).toString("hex")}`;
}

import { Buffer } from "buffer";

import type { ClaimCheck } from "./contracts/fuul-manager/index.js";
import { toBytes32, type Bytes32Input } from "./bytes.js";
import {
  validateAddress,
  validateContractId,
  validateUnsignedBigInt,
} from "./validation.js";

const MAX_I128 = (1n << 127n) - 1n;
const MAX_U32 = (1n << 32n) - 1n;
const MAX_U256 = (1n << 256n) - 1n;

export const currencyType = {
  stellarAsset: { tag: "StellarAsset", values: undefined },
  nonFungible: { tag: "NonFungible", values: undefined },
  multiToken: { tag: "MultiToken", values: undefined },
} as const;

export const claimReason = {
  affiliatePayout: { tag: "AffiliatePayout", values: undefined },
  endUserPayout: { tag: "EndUserPayout", values: undefined },
} as const;

export interface ClaimCheckInput {
  project: string;
  to: string;
  currency: string;
  currencyType: ClaimCheck["currency_type"];
  amount: bigint;
  reason: ClaimCheck["reason"];
  tokenId?: bigint;
  deadline: bigint;
  proof: Bytes32Input;
  signers: readonly string[];
}

export function createClaimCheck(input: ClaimCheckInput): ClaimCheck {
  validateContractId(input.project, "project");
  validateAddress(input.to, "to");
  validateContractId(input.currency, "currency");
  validateUnsignedBigInt(input.amount, MAX_I128, "amount");
  const tokenId = input.tokenId === undefined ? 0n : input.tokenId;
  validateUnsignedBigInt(tokenId, MAX_U256, "tokenId");
  if (!["StellarAsset", "NonFungible", "MultiToken"].includes(input.currencyType?.tag)) {
    throw new TypeError("currencyType must be a supported Fuul asset kind");
  }
  if (!["AffiliatePayout", "EndUserPayout"].includes(input.reason?.tag)) {
    throw new TypeError("reason must be a supported Fuul claim reason");
  }
  if (input.currencyType.tag !== "StellarAsset" && tokenId > MAX_U32) {
    throw new RangeError("tokenId must fit the pinned u32 asset adapter interface");
  }
  validateUnsignedBigInt(input.deadline, MAX_U256, "deadline");
  if (input.signers.length === 0) {
    throw new TypeError("at least one claim signer is required");
  }

  const uniqueSigners = new Set<string>();
  for (const signer of input.signers) {
    validateAddress(signer, "signer");
    if (uniqueSigners.has(signer)) {
      throw new TypeError("claim signers must be unique");
    }
    uniqueSigners.add(signer);
  }

  return {
    project_address: input.project,
    to: input.to,
    currency: input.currency,
    currency_type: { tag: input.currencyType.tag, values: undefined },
    amount: input.amount,
    reason: { tag: input.reason.tag, values: undefined },
    token_id: tokenId,
    deadline: input.deadline,
    proof: toBytes32(input.proof, "proof"),
    signers: [...input.signers],
  };
}

export function randomClaimProof(): Buffer {
  return Buffer.from(globalThis.crypto.getRandomValues(new Uint8Array(32)));
}

import type { Client, MethodOptions } from "@stellar/stellar-sdk/contract";
import { FuulError } from "./errors.js";

export function assertUnsignedCall(options?: MethodOptions): void {
  if (options?.signTransaction || options?.signAuthEntry || options?.restore) {
    throw new FuulError("INVALID_TRANSACTION", "Use the executor for signing and prepare restoration separately");
  }
}

/** Validate method options before upstream simulation can start an automatic restore. */
export function unsignedClient<T extends Client>(client: T): T {
  for (const fn of client.spec.funcs()) {
    const name = fn.name.toString();
    if (name === "__constructor") continue;
    const methods = client as unknown as Record<string, (...args: unknown[]) => unknown>;
    const method = methods[name]!;
    const optionsIndex = fn.inputs.length ? 1 : 0;
    methods[name] = (...args: unknown[]) => {
      assertUnsignedCall(client.options);
      assertUnsignedCall(args[optionsIndex] as MethodOptions | undefined);
      return method.apply(client, args);
    };
  }
  return client;
}

