        e.storage()
            .persistent()
            .set(&(from, token_id), &(balance - amount));
        let next = Self::balance(e.clone(), to.clone(), token_id)
            .checked_add(amount)
            .unwrap();
        e.storage().persistent().set(&(to, token_id), &next);
    }
