      expect(createHash("sha256").update(wasm).digest("hex")).toBe(artifact.wasmSha256);
      expect(Buffer.from(await operation(`upload ${name} upgrade fixture`, Operation.uploadContractWasm({ wasm }))).toString("hex")).toBe(artifact.wasmSha256);
      const original = await instance(client.options.contractId);
      expect(Buffer.from(original.hash).toString("hex")).toBe(artifact.previousWasmSha256);
      const args = { new_wasm_hash: Buffer.from(artifact.wasmSha256, "hex"), operator: address };
      const sequence = (await rpc.getAccount(address)).sequenceNumber();
      // Manager and Factory check their own role (OpenZeppelin 2000); a Project checks the Factory role (Project 6101).
      await expect(send("unauthorized upgrade must fail", () => client.upgrade({ ...args, operator: recipient.publicKey() })))
        .rejects.toMatchObject({ code: "CONTRACT_ERROR", details: { contractCode: name === "project" ? 6101 : 2000 } });
      expect((await rpc.getAccount(address)).sequenceNumber()).toBe(sequence);
      await send(`upgrade ${name}`, () => client.upgrade(args));
      const record = records.at(-1)!;
      const changed = await instance(client.options.contractId);
      expect(Buffer.from(changed.hash).toString("hex")).toBe(artifact.wasmSha256);
      expect(changed.storageXdr).toBe(original.storageXdr);
      const included = await rpc.getTransaction(record.hash);
      expect(included.status).toBe(Api.GetTransactionStatus.SUCCESS);
      if (included.status !== Api.GetTransactionStatus.SUCCESS) throw new Error("Upgrade was not included successfully");
      const events = included.events.contractEventsXdr.flat()
        .filter(event => {
          const hash = event.contractId?.toBytes();
          return hash !== undefined && Buffer.from(hash).equals(StrKey.decodeContract(client.options.contractId));
        })
        .map(event => ({ topics: event.body.v0.topics.map(scValToNative), data: scValToNative(event.body.v0.data) }));
      expect(events).toEqual([
        { topics: ["executable_update", ["Wasm", original.hash], ["Wasm", changed.hash]], data: [] },
        { topics: ["contract_upgraded"], data: { operator: address, new_wasm_hash: changed.hash } },
      ]);
      upgradeContractHashes[`fuul-${name}`] = artifact.wasmSha256;
      expect(await readContract(fixtureCall<number>(client.options.contractId, "fixture_schema_version", []))).toBe(0);
      await expect(send("unauthorized migration must fail", () => fixtureCall(client.options.contractId, "migrate_fixture", [new Address(recipient.publicKey()).toScVal()])))
        .rejects.toMatchObject({ code: "CONTRACT_ERROR", details: { contractCode: 2000 } });
      await send(`migrate upgraded ${name}`, () => fixtureCall(client.options.contractId, "migrate_fixture", [new Address(address).toScVal()]));
      expect(await readContract(fixtureCall<number>(client.options.contractId, "fixture_schema_version", []))).toBe(2);
      await expect(send("repeated migration must fail", () => fixtureCall(client.options.contractId, "migrate_fixture", [new Address(address).toScVal()])))
        .rejects.toMatchObject({ code: "CONTRACT_ERROR", details: { contractCode: 6900 } });
      expect(await state()).toEqual(before);
      transitions.push({ name, contractId: client.options.contractId, previousWasm: Buffer.from(original.hash).toString("hex"),
        newWasm: Buffer.from(changed.hash).toString("hex"), upgrade: record.hash, ledger: record.ledger });
    }
    await send("unpause after contract upgrades", () => sdk.manager.unpause({ caller: address }));
    const beforeNext = await balances();
    const replaySequence = (await rpc.getAccount(address)).sequenceNumber();
    await expect(send("upgraded replay must fail", () => sdk.manager.claim({ caller: address, checks: [projectClaim] }), claimAuthorizations(sdk.manager.options.contractId, [projectClaim])))
      .rejects.toMatchObject({ code: "CONTRACT_ERROR", details: { contractCode: 6102 } });
    expect((await rpc.getAccount(address)).sequenceNumber()).toBe(replaySequence);
    expect(await balances()).toEqual(beforeNext);
    const next = { ...projectClaim, proof: randomClaimProof(), amount: 1_000_000n };
    const fees = await readContract(sdk.factory.get_fees_information({ project: projectId }));
    const fee = calculateFee(next.amount, fees.fees.project_claim_fee);
    await send("claim after all upgrades", () => sdk.manager.claim({ caller: address, checks: [next] }), claimAuthorizations(sdk.manager.options.contractId, [next]));
    expect(await balances()).toEqual([beforeNext[0]! - next.amount - fee, beforeNext[1]! + next.amount, beforeNext[2]! + fee, beforeNext[3]! + next.amount]);
    expect(await readContract(project.claimed_proofs({ proof: projectClaim.proof }))).toBe(true);
    expect(await readContract(project.claimed_proofs({ proof: next.proof }))).toBe(true);
    await writeFile(new URL(`../.local/upgrades-${evidenceTag}.json`, import.meta.url), JSON.stringify({
      networkPassphrase, protocol: Number(protocol), transitions, replayContractCode: 6102,
      subsequentClaim: records.at(-1), fixtureSourceCommit: provenance.coreSourceCommit,
    }, null, 2) + "\n");
  }, 300_000);
  test("relays a claim only with the caller's exact native fee consent", async () => {
    const caller = recipient.publicKey();
    const actions = new FuulActions(sdk, executor);
    const input = { caller, checks: [{ project: projectId, to: caller, currency, currencyType: currencyType.stellarAsset,
      amount: 1_000n, reason: claimReason.endUserPayout, deadline: BigInt(Math.floor(Date.now() / 1000) + 600), proof: randomClaimProof(), signers: [claimSigner.publicKey()] }],
      nativeFee: { asset: native, collector: collector.publicKey(), amount: 20_000n } };
    const sequence = (await rpc.getAccount(address)).sequenceNumber();
    const before = await readContract(sdk.token(native).balance(caller));
    await expect(actions.claimRewards({ ...input, nativeFee: { ...input.nativeFee, amount: 20_001n } }))
      .rejects.toMatchObject({ code: "INVALID_TRANSACTION" });
    expect((await rpc.getAccount(address)).sequenceNumber()).toBe(sequence);
    const receipt = await actions.claimRewards(input);
    records.push({ name: "relayed claim with exact native fee", hash: receipt.hash, ledger: receipt.ledger });
    expect(before - await readContract(sdk.token(native).balance(caller))).toBe(20_000n);
  });
});

async function withLocalDeadline<T>(promise: Promise<T>, timeoutMs: number): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([promise, new Promise<never>((_, reject) => {
      timer = setTimeout(() => reject(new Error("Wallet cancellation fixture exceeded its deadline")), timeoutMs);
    })]);
  } finally { clearTimeout(timer); }
}

function fixtureCall<T = unknown>(contractId: string, method: string, args: xdr.ScVal[]) {
  return AssembledTransaction.build<T>({ ...network, contractId, method, args, parseResultXdr: result => scValToNative(result) as T });
}

import { Networks, StrKey } from "@stellar/stellar-sdk";
import type { Server } from "@stellar/stellar-sdk/rpc";

export const target = process.env.FUUL_E2E_NETWORK ?? "local";
if (!["local", "testnet"].includes(target)) throw new Error("E2E supports only local or Testnet");
export const protocol = process.env.FUUL_E2E_PROTOCOL ?? "28";
if (target === "local" ? !["27", "28"].includes(protocol)
  : !/^[1-9][0-9]{0,8}$/.test(protocol) || Number(protocol) < 27) {
  throw new Error("Local protocols must be 27 or 28; Testnet requires Protocol 27 or later");
}
const port = process.env.FUUL_E2E_PORT ?? "18010";
if (!/^[0-9]{4,5}$/.test(port) || Number(port) > 65535 || Number(port) < 1024) throw new Error("Invalid local test port");
export const allowHttp = target === "local";
export const rpcUrl = allowHttp ? `http://127.0.0.1:${port}/soroban/rpc` : "https://soroban-testnet.stellar.org";
export const networkPassphrase = allowHttp ? Networks.STANDALONE : Networks.TESTNET;
export const evidenceTag = `${target}-${protocol}`;

export async function guardNetwork(rpc: Pick<Server, "getNetwork" | "getHealth">): Promise<void> {
  const [network, health] = await Promise.all([rpc.getNetwork(), rpc.getHealth()]);
  if (network.passphrase !== networkPassphrase || Number(network.protocolVersion) !== Number(protocol) || health.status !== "healthy") {
    throw new Error("E2E network identity or health does not match the selected target");
  }
}

/** Keys remain in memory. Only disposable account public keys reach Friendbot. */
export async function fundTestAccount(rpc: Pick<Server, "getNetwork" | "getHealth" | "getAccount">, account: string): Promise<void> {
  if (!StrKey.isValidEd25519PublicKey(account)) throw new Error("Invalid account public key");
  await guardNetwork(rpc);
  const faucet = allowHttp ? `http://127.0.0.1:${port}/friendbot` : "https://friendbot.stellar.org/";
  const deadline = Date.now() + 120_000;
  while (Date.now() < deadline) {
    try { await rpc.getAccount(account); return; } catch { /* The disposable account can be absent. */ }
    try {
      const response = await fetch(`${faucet}?addr=${account}`, { signal: AbortSignal.timeout(20_000), redirect: "error" });
      if (response.ok) { await rpc.getAccount(account); return; }
      if (response.status < 500 && ![400, 429].includes(response.status)) throw new Error(`Friendbot rejected funding: ${response.status}`);
    } catch (error) {
      if (error instanceof Error && error.message.startsWith("Friendbot rejected")) throw error;
    }
    await Bun.sleep(1000);
  }
  await rpc.getAccount(account);
}

import { expect, test } from "bun:test";
import { randomUUID } from "node:crypto";
import { arm } from "../test/fixtures/xdr.js";
import { mkdir, writeFile } from "node:fs/promises";
import { Address, Asset, Contract, Keypair, Operation, Transaction, TransactionBuilder } from "@stellar/stellar-sdk";
import { checkSorobanResources, createFuulRpcServer, inspectSorobanResources, readSorobanResourceLimits, submitSignedTransaction } from "@fuul/sdk-stellar";
import { protocol, target, networkPassphrase, rpcUrl, allowHttp, fundTestAccount, guardNetwork } from "./network.js";

test("resource checks agree with Core rejection and permit signed normal and fee-bump calls", async () => {
  const rpc = createFuulRpcServer(rpcUrl, { allowHttp });
  await guardNetwork(rpc);
  const network = await rpc.getNetwork();
  expect(network.passphrase).toBe(networkPassphrase); expect(Number(network.protocolVersion)).toBe(Number(protocol));
  const source = Keypair.random(), payer = Keypair.random();
  const records: Record<string, unknown>[] = []; let passed = false;
  const evidence: Record<string, unknown> = { protocol: Number(protocol), networkPassphrase, rpcUrl, source: source.publicKey(), payer: payer.publicKey(), records };
  try {
    for (const key of [source, payer]) {
      await fundTestAccount(rpc, key.publicKey());
    }
    const token = new Contract(Asset.native().contractId(networkPassphrase));
    const send = async (name: string, signed: Parameters<typeof submitSignedTransaction>[1]) => {
      const report = await checkSorobanResources(rpc, signed);
      expect(report?.violations).toEqual([]);
      const result = await submitSignedTransaction(rpc, signed, { pollIntervalMs: 250 });
      expect(result.envelopeXdr.toXdr("base64")).toBe(signed.toXdr());
      records.push({ name, report, hash: Buffer.from(signed.hash()).toString("hex"), ledger: result.ledger,
        envelopeXdr: signed.toXdr(), resultXdr: result.resultXdr.toXdr("base64"), resultMetaXdr: result.resultMetaXdr.toXdr("base64") });
      return result;
    };
    if (!(await rpc.getLedgerEntries(token.getFootprint())).entries.length) {
      const deploy = await rpc.prepareTransaction(new TransactionBuilder(await rpc.getAccount(source.publicKey()), { networkPassphrase, fee: "100" })
        .addOperation(Operation.createStellarAssetContract({ asset: Asset.native() })).setTimeout(120).build());
      deploy.sign(source); await send("deploy native SAC", deploy);
    }
    const prepare = async () => rpc.prepareTransaction(new TransactionBuilder(await rpc.getAccount(source.publicKey()), { networkPassphrase, fee: "100" })
      .addOperation(token.call("balance", new Address(source.publicKey()).toScVal())).setTimeout(120).build());
    const valid = await prepare(), limits = await readSorobanResourceLimits({ getNetwork: rpc.getNetwork.bind(rpc), async getLedgerEntries(...keys) {
      const response = await rpc.getLedgerEntries(...keys);
      evidence.configuration = { ledger: response.latestLedger, entries: response.entries.map(entry => ({ keyXdr: entry.key.toXdr("base64"), valueXdr: entry.val.toXdr("base64") })) };
      return response;
    } }, networkPassphrase);
    evidence.limits = limits;
    const envelope = valid.toEnvelope();
    const over = limits.maximum.instructions + 1n;
    if (over > 0xffff_ffffn) throw new Error("Cannot construct a one-unit-over instruction declaration");
    const resources = arm(arm(envelope, "envelopeTypeTx").v1.tx.ext, "sorobanData").sorobanData.resources;
    Reflect.set(resources, "instructions", Number(over));
    const invalid = new Transaction(envelope, networkPassphrase); invalid.sign(source);
    expect(inspectSorobanResources(invalid, limits)!.violations).toContainEqual({ resource: "instructions", actual: String(over), maximum: String(limits.maximum.instructions) });
    const sequence = (await rpc.getAccount(source.publicKey())).sequenceNumber();
    let broadcasts = 0;
    const guardedRpc = {
      getNetwork: rpc.getNetwork.bind(rpc), getLedgerEntries: rpc.getLedgerEntries.bind(rpc), getTransaction: rpc.getTransaction.bind(rpc),
      sendTransaction: async (...args: Parameters<typeof rpc.sendTransaction>) => { broadcasts++; return rpc.sendTransaction(...args); },
    };
    await expect(submitSignedTransaction(guardedRpc, invalid)).rejects.toMatchObject({ code: "RESOURCE_LIMIT", details: { resource: "instructions" } });
    expect(broadcasts).toBe(0);
    // Deliberately submit this invalid test envelope directly to Core as an independent oracle.
    const rejected = await rpc.sendTransaction(invalid);
    expect(rejected.status).toBe("ERROR");
    expect(rejected.errorResult?.result.type).toBe("txSorobanInvalid");
    expect((await rpc.getAccount(source.publicKey())).sequenceNumber()).toBe(sequence);
    evidence.rejected = { hash: Buffer.from(invalid.hash()).toString("hex"), envelopeXdr: invalid.toXdr(), status: rejected.status,
      resultXdr: rejected.errorResult?.toXdr("base64"), diagnostics: rejected.diagnosticEvents?.map(event => event.toXdr("base64")), sdkBroadcasts: broadcasts, sequenceUnchanged: true };
    valid.sign(source); await send("native balance", valid);
    const inner = await prepare(); inner.sign(source);
    const outer = TransactionBuilder.buildFeeBumpTransaction(payer, "1000", inner, networkPassphrase); outer.sign(payer);
    const report = await checkSorobanResources(rpc, outer);
    expect(report!.usage.transactionBytes).toBe(BigInt(inner.toEnvelope().toXdr().length));
    expect(report!.usage.transactionBytes).toBeLessThan(BigInt(outer.toEnvelope().toXdr().length));
    await send("fee-bump native balance", outer);
    passed = true;
  } finally {
    const directory = new URL("../.local/", import.meta.url); await mkdir(directory, { recursive: true });
    const output = new URL(`resource-admission-${target}-${protocol}-${randomUUID()}.json`, directory);
    await writeFile(output, JSON.stringify({ ...evidence, passed }, (_, value) => typeof value === "bigint" ? String(value) : value, 2) + "\n", { flag: "wx" });
    console.info(JSON.stringify({ resourceEvidence: output.pathname, passed, receipts: records.length }));
  }
}, 180_000);

