    assert.equal(cleanup.status, 0, 'Could not remove this test network');
  }
  await writeFile(join(output, `${id}.json`), JSON.stringify({ target, protocol: Number(protocol), passed, finishedAt: new Date().toISOString() }, null, 2) + '\n');
}

