      expect(() => bytesToHex(value as never)).toThrow(TypeError);
    }
    expect(() => toBytes32(`0x${"gg".repeat(32)}`)).toThrow(TypeError);
  });
});

import { describe, expect, test } from "bun:test";
import { Keypair, StrKey } from "@stellar/stellar-sdk";
import { Buffer } from "buffer";

import {
  currencyType,
  claimReason,
  createClaimCheck,
  randomClaimProof,
} from "../src/index.js";

const project = StrKey.encodeContract(Buffer.alloc(32, 1));
const currency = StrKey.encodeContract(Buffer.alloc(32, 2));
const recipient = Keypair.fromRawEd25519Seed(Buffer.alloc(32, 3)).publicKey();
const signer = Keypair.fromRawEd25519Seed(Buffer.alloc(32, 4)).publicKey();

describe("claim helpers", () => {
  test("builds the manager binding shape without changing business fields", () => {
    const proof = Buffer.alloc(32, 7);
    const claim = createClaimCheck({
      project,
      to: recipient,
      currency,
      currencyType: currencyType.stellarAsset,
      amount: 100n,
      reason: claimReason.affiliatePayout,
      deadline: 1_800_000_000n,
      proof,
      signers: [signer],
    });

    expect(claim).toEqual({
      project_address: project,
      to: recipient,
      currency,
      currency_type: { tag: "StellarAsset", values: undefined },
      amount: 100n,
      reason: { tag: "AffiliatePayout", values: undefined },
      token_id: 0n,
      deadline: 1_800_000_000n,
      proof,
      signers: [signer],
    });
    expect(claim.proof).not.toBe(proof);
  });

  test("rejects malformed and ambiguous claims before simulation", () => {
    const base = {
      project,
      to: recipient,
      currency,
      currencyType: currencyType.stellarAsset,
      amount: 100n,
      reason: claimReason.endUserPayout,
      deadline: 1_800_000_000n,
      proof: Buffer.alloc(32),
      signers: [signer],
    };

    expect(() => createClaimCheck({ ...base, amount: -1n })).toThrow(RangeError);
    expect(() => createClaimCheck({ ...base, proof: Buffer.alloc(31) })).toThrow(TypeError);
    expect(() => createClaimCheck({ ...base, signers: [] })).toThrow("at least one");
    expect(() => createClaimCheck({ ...base, signers: [signer, signer] })).toThrow("unique");
  });

  test("enforces the pinned token identifier range for asset adapters", () => {
    const base = {
      project,
      to: recipient,
      currency,
      currencyType: currencyType.nonFungible,
      amount: 0n,
      reason: claimReason.endUserPayout,
      deadline: 1_800_000_000n,
      proof: Buffer.alloc(32),
      signers: [signer],
    };

    expect(createClaimCheck({ ...base, tokenId: (1n << 32n) - 1n }).token_id).toBe(
      (1n << 32n) - 1n,
    );
    expect(() => createClaimCheck({ ...base, tokenId: 1n << 32n })).toThrow(
      "pinned u32 asset adapter interface",
    );
    expect(() =>
      createClaimCheck({ ...base, currencyType: currencyType.multiToken, tokenId: 1n << 32n }),
    ).toThrow("pinned u32 asset adapter interface");
  });

  test("creates 32-byte replay proofs", () => {
    const first = randomClaimProof();
    const second = randomClaimProof();
    expect(first).toHaveLength(32);
    expect(second).toHaveLength(32);
    expect(first).not.toEqual(second);
  });

  test("validates runtime address kinds enums and integer types", () => {
    const base = {
      project, currency, to: recipient, currencyType: currencyType.stellarAsset,
      amount: 100n, reason: claimReason.endUserPayout, deadline: 1_800_000_000n,
      proof: Buffer.alloc(32), signers: [signer],
    };
    for (const address of [
      StrKey.encodeMed25519PublicKey(Buffer.alloc(40)),
      StrKey.encodeLiquidityPool(Buffer.alloc(32)),
      StrKey.encodeClaimableBalance(Buffer.alloc(33)),
    ]) {
      expect(() => createClaimCheck({ ...base, to: address })).toThrow(TypeError);
      expect(() => createClaimCheck({ ...base, signers: [address] })).toThrow(TypeError);
    }
    expect(() => createClaimCheck({ ...base, project: recipient })).toThrow(TypeError);
    expect(() => createClaimCheck({ ...base, currency: recipient })).toThrow(TypeError);
    expect(createClaimCheck({ ...base, to: project, signers: [project] }).to).toBe(project);
    for (const value of [100, NaN, Infinity, "100", null, undefined]) {
      expect(() => createClaimCheck({ ...base, amount: value as unknown as bigint })).toThrow(TypeError);
      expect(() => createClaimCheck({ ...base, deadline: value as unknown as bigint })).toThrow(TypeError);
    }
    expect(() => createClaimCheck({ ...base, tokenId: 1 as unknown as bigint })).toThrow(TypeError);
    expect(() => createClaimCheck({ ...base, tokenId: null as unknown as bigint })).toThrow(TypeError);
    expect(() => createClaimCheck({ ...base, amount: 1n << 127n })).toThrow(RangeError);
    expect(() => createClaimCheck({ ...base, deadline: 1n << 256n })).toThrow(RangeError);
    expect(() => createClaimCheck({ ...base, currencyType: { tag: "Unknown" } as never })).toThrow(TypeError);
    expect(() => createClaimCheck({ ...base, reason: { tag: "Unknown" } as never })).toThrow(TypeError);
  });

  test("copies all mutable claim inputs", () => {
    const input = {
      project, currency, to: recipient,
      currencyType: { ...currencyType.stellarAsset }, reason: { ...claimReason.endUserPayout },
      amount: 100n, deadline: 1_800_000_000n, proof: Buffer.alloc(32, 1), signers: [signer],
    };
    const claim = createClaimCheck(input);
    Reflect.set(input.currencyType, "tag", "NonFungible");
    Reflect.set(input.reason, "tag", "AffiliatePayout");
    input.proof.fill(2);
    input.signers[0] = recipient;
    expect(claim.currency_type.tag).toBe("StellarAsset");
    expect(claim.reason.tag).toBe("EndUserPayout");
    expect(claim.proof).toEqual(Buffer.alloc(32, 1));
    expect(claim.signers).toEqual([signer]);
  });

  test("accepts full unsigned claim intent without widening transfer or adapter amounts", () => {
    const maximum = (1n << 256n) - 1n;
    const input = {
      project, currency, to: recipient, currencyType: currencyType.stellarAsset,
      amount: (1n << 127n) - 1n, reason: claimReason.endUserPayout,
      deadline: maximum, tokenId: maximum, proof: Buffer.alloc(32, 1), signers: [signer],
    };
    expect(createClaimCheck(input)).toMatchObject({ deadline: maximum, token_id: maximum, amount: input.amount });
    for (const field of ["deadline", "tokenId"] as const) {
      for (const value of [-1n, 1n << 256n]) {
        expect(() => createClaimCheck({ ...input, [field]: value })).toThrow(RangeError);
      }
    }
    expect(() => createClaimCheck({ ...input, amount: 1n << 127n })).toThrow(RangeError);
    for (const kind of [currencyType.nonFungible, currencyType.multiToken]) {
      expect(() => createClaimCheck({ ...input, currencyType: kind })).toThrow("pinned u32");
    }
  });
});

import { arm } from "./fixtures/xdr.js";
import { expect, spyOn, test } from "bun:test";
import { Account, Asset, FeeBumpTransaction, Keypair, Memo, Networks, Operation, Transaction, TransactionBuilder, xdr } from "@stellar/stellar-sdk";
import { cosignPreparedTransaction, keypairSigner, signPreparedTransaction, type CosignOptions, type FuulSigner } from "../src/index.js";

const source = Keypair.random();
const first = Keypair.random();
const second = Keypair.random();
const destination = Keypair.random();
const networkPassphrase = Networks.STANDALONE;

function prepared() {
  return new TransactionBuilder(new Account(source.publicKey(), "42"), { networkPassphrase, fee: "100" })
    .addOperation(Operation.payment({ destination: destination.publicKey(), asset: Asset.native(), amount: "1" }))
    .setTimeout(300).build();
}
function review(tx: Transaction | FeeBumpTransaction): CosignOptions {
  return { expectedSource: tx instanceof FeeBumpTransaction ? tx.feeSource : tx.source, expectedHash: Buffer.from(tx.hash()).toString("hex"), maxFeeStroops: 10_000n };
}
function wallet(change: (tx: Transaction | FeeBumpTransaction) => Transaction | FeeBumpTransaction, key = first): FuulSigner {
  return { address: key.publicKey(), async signTransaction(encoded, options) {
    const tx = change(TransactionBuilder.fromXdr(encoded, options!.networkPassphrase!));
    return { signedTxXdr: tx.toXdr(), signerAddress: key.publicKey() };
  } };
}

test("two account cosigners sign the same reviewed body without changing caller-owned envelopes", async () => {
  const tx = prepared(); const original = tx.toXdr(); const reviewed = review(tx);
  const one = await cosignPreparedTransaction(tx, keypairSigner(first), reviewed);
  const snapshot = one.toXdr(); const two = await cosignPreparedTransaction(one, keypairSigner(second), reviewed);
  expect(tx.toXdr()).toBe(original); expect(one.toXdr()).toBe(snapshot);
  expect(one.signatures).toHaveLength(1); expect(two.signatures).toHaveLength(2);
  expect(two.source).toBe(source.publicKey()); expect(Buffer.from(two.hash()).toString("hex")).toBe(reviewed.expectedHash);
  expect(first.verify(two.hash(), two.signatures[0]!.signature.toBytes())).toBe(true);
  expect(second.verify(two.hash(), two.signatures[1]!.signature.toBytes())).toBe(true);
  await expect(signPreparedTransaction(tx, keypairSigner(first), reviewed.maxFeeStroops)).rejects.toMatchObject({ code: "INVALID_TRANSACTION" });
});

test("the wallet receives the selected cosigner, network, reviewed XDR and submit false", async () => {
  const tx = prepared(); let calls = 0;
  class Wallet implements FuulSigner {
    #signer = keypairSigner(first);
    get address() { return first.publicKey(); }
    async signTransaction(...args: Parameters<FuulSigner["signTransaction"]>) {
      calls++;
      expect(args[0]).toBe(tx.toXdr());
      expect(args[1]).toEqual({ networkPassphrase, address: first.publicKey(), submit: false });
      return this.#signer.signTransaction(...args);
    }
  }
  expect((await cosignPreparedTransaction(tx, new Wallet(), review(tx))).signatures).toHaveLength(1);
  expect(calls).toBe(1);
});

test("source, hash, network, fee and expiry mismatches stop before wallet interaction", async () => {
  let calls = 0; const signer: FuulSigner = { address: first.publicKey(), async signTransaction() { calls++; throw new Error("Unexpected signing request"); } };
  const tx = prepared(); const options = review(tx);
  for (const altered of [
    { ...options, expectedSource: first.publicKey() }, { ...options, expectedHash: "00".repeat(32) },
    { ...options, expectedHash: options.expectedHash.toUpperCase() }, { ...options, maxFeeStroops: 99n }, { ...options, maxFeeStroops: 0n },
  ]) await expect(cosignPreparedTransaction(tx, signer, altered)).rejects.toThrow();
  const networkChanged = new Transaction(tx.toXdr(), Networks.TESTNET);
  await expect(cosignPreparedTransaction(networkChanged, signer, options)).rejects.toMatchObject({ code: "INVALID_TRANSACTION" });
  const envelope = tx.toEnvelope(); Reflect.set(arm(arm(envelope, "envelopeTypeTx").v1.tx.cond, "precondTime").timeBounds, "maxTime", xdr.Uint64.fromString("1"));
  const expired = new Transaction(envelope, networkPassphrase);
  await expect(cosignPreparedTransaction(expired, signer, review(expired))).rejects.toMatchObject({ code: "INVALID_TRANSACTION" });
  expect(calls).toBe(0);
});

test("wallet body changes and wrong-network signatures cannot satisfy a reviewed hash", async () => {
  const tx = prepared(); const options = review(tx);
  for (const mutate of [
    (value: Transaction | FeeBumpTransaction) => { const changed = TransactionBuilder.cloneFrom(value as Transaction).addMemo(Memo.text("changed")).build(); changed.sign(first); return changed; },
    (value: Transaction | FeeBumpTransaction) => { const changed = new Transaction(value.toXdr(), Networks.TESTNET); changed.sign(first); return changed; },
  ]) await expect(cosignPreparedTransaction(tx, wallet(mutate), options)).rejects.toMatchObject({ code: "WALLET_MUTATION" });
});

test("a wallet cannot substitute a legacy envelope even when its transaction hash matches", async () => {
  const tx = prepared();
  const v1 = arm(tx.toEnvelope(), "envelopeTypeTx").v1.tx;
  const legacy = new Transaction(xdr.TransactionEnvelope.envelopeTypeTxV0(new xdr.TransactionV0Envelope({
    tx: new xdr.TransactionV0({ sourceAccountEd25519: source.rawPublicKey(), fee: v1.fee, seqNum: v1.seqNum,
      timeBounds: arm(v1.cond, "precondTime").timeBounds, memo: v1.memo, operations: v1.operations, ext: xdr.TransactionV0Ext.v0() }),
    signatures: [],
  })), networkPassphrase);
  legacy.sign(first);
  expect(Buffer.from(legacy.hash()).equals(tx.hash())).toBe(true);
  expect(first.verify(tx.hash(), legacy.signatures[0]!.signature.toBytes())).toBe(true);
  await expect(cosignPreparedTransaction(tx, wallet(() => legacy), review(tx))).rejects.toMatchObject({ code: "WALLET_MUTATION" });
});

test("wallets must append exactly one valid signature from the selected key", async () => {
  const tx = prepared();
  for (const alter of [
    (value: Transaction | FeeBumpTransaction) => value,
    (value: Transaction | FeeBumpTransaction) => { value.sign(second); return value; },
    (value: Transaction | FeeBumpTransaction) => { value.sign(first, first); return value; },
    (value: Transaction | FeeBumpTransaction) => { value.sign(first); Reflect.set(value.signatures[0]!, "signature", new xdr.Signature(Buffer.alloc(64))); return value; },
    (value: Transaction | FeeBumpTransaction) => { value.sign(first); Reflect.set(value.signatures[0]!, "hint", new xdr.SignatureHint(Buffer.alloc(4))); return value; },
  ]) await expect(cosignPreparedTransaction(tx, wallet(alter), review(tx))).rejects.toMatchObject({ code: "WALLET_MUTATION" });
});

test("wallets cannot remove, reorder, replace or duplicate earlier account signatures", async () => {
  const tx = prepared(); tx.sign(source, second);
  for (const alter of [
    (value: Transaction | FeeBumpTransaction) => { value.signatures.splice(0, 1); value.sign(first); return value; },
    (value: Transaction | FeeBumpTransaction) => { value.signatures.reverse(); value.sign(first); return value; },
    (value: Transaction | FeeBumpTransaction) => { value.signatures[0] = value.signatures[1]!; value.sign(first); return value; },
    (value: Transaction | FeeBumpTransaction) => { value.sign(first); value.signatures.push(value.signatures[0]!); return value; },
  ]) await expect(cosignPreparedTransaction(tx, wallet(alter), review(tx))).rejects.toMatchObject({ code: "WALLET_MUTATION" });
});

test("an existing valid signature from this cosigner is rejected without another wallet prompt", async () => {
  const tx = prepared(); tx.sign(first); let calls = 0;
  await expect(cosignPreparedTransaction(tx, { address: first.publicKey(), async signTransaction() { calls++; throw new Error("must not sign twice"); } }, review(tx))).rejects.toMatchObject({ code: "INVALID_TRANSACTION" });
  expect(calls).toBe(0);
});

test("a fee source can collect multiple signatures while retaining its signed inner transaction", async () => {
  const inner = prepared(); inner.sign(source); const innerXdr = inner.toXdr();
  const feeBump = TransactionBuilder.buildFeeBumpTransaction(destination.publicKey(), "200", inner, networkPassphrase);
  const one = await cosignPreparedTransaction(feeBump, keypairSigner(first), review(feeBump));
  const two = await cosignPreparedTransaction(one, keypairSigner(second), review(feeBump));
  expect(two).toBeInstanceOf(FeeBumpTransaction); expect(two.innerTransaction.toXdr()).toBe(innerXdr);
  expect(two.feeSource).toBe(destination.publicKey()); expect(two.signatures).toHaveLength(2);
  expect(first.verify(two.hash(), two.signatures[0]!.signature.toBytes())).toBe(true);
  expect(second.verify(two.hash(), two.signatures[1]!.signature.toBytes())).toBe(true);
  const unsignedInner = TransactionBuilder.buildFeeBumpTransaction(destination.publicKey(), "200", prepared(), networkPassphrase);
  await expect(cosignPreparedTransaction(unsignedInner, keypairSigner(first), review(unsignedInner))).rejects.toMatchObject({ code: "INVALID_TRANSACTION" });
});

test("cancellation settles while a wallet waits and rejects its late signature", async () => {
  const tx = prepared(); const controller = new AbortController();
  let entered!: () => void, release!: () => void;
  const started = new Promise<void>(resolve => { entered = resolve; }); const wait = new Promise<void>(resolve => { release = resolve; });
  const signer = keypairSigner(first);
  const result = cosignPreparedTransaction(tx, { address: first.publicKey(), async signTransaction(...args) { entered(); await wait; return signer.signTransaction(...args); } }, { ...review(tx), signal: controller.signal });
  await started; controller.abort();
  try { await expect(result).rejects.toMatchObject({ code: "ABORTED" }); }
  finally { release(); }
  expect(tx.signatures).toHaveLength(0);
});

test("review options, caller envelope and signer fields are snapshotted before wallet wait", async () => {
  const tx = prepared(); const original = tx.toXdr(); const options = review(tx);
  const signer: FuulSigner = { address: first.publicKey(), async signTransaction(encoded, parameters) {
    options.expectedHash = "00".repeat(32); options.expectedSource = second.publicKey(); options.maxFeeStroops = 1n;
    tx.sign(second); signer.address = second.publicKey();
    const value = TransactionBuilder.fromXdr(encoded, parameters!.networkPassphrase!); value.sign(first);
    return { signedTxXdr: value.toXdr(), signerAddress: first.publicKey() };
  } };
  const signed = await cosignPreparedTransaction(tx, signer, options);
  expect(Buffer.from(signed.hash()).equals(new Transaction(original, networkPassphrase).hash())).toBe(true);
  expect(signed.signatures).toHaveLength(1); expect(first.verify(signed.hash(), signed.signatures[0]!.signature.toBytes())).toBe(true);
});

test("malformed wallet envelopes and wrong signer identity are rejected", async () => {
  const tx = prepared();
  for (const response of [
    { signedTxXdr: "invalid", signerAddress: first.publicKey() },
    { signedTxXdr: tx.toXdr() + "\n", signerAddress: first.publicKey() },
    { signedTxXdr: "A".repeat(2 * 1024 * 1024 + 1), signerAddress: first.publicKey() },
    { signedTxXdr: tx.toXdr(), signerAddress: second.publicKey() },
  ]) await expect(cosignPreparedTransaction(tx, { address: first.publicKey(), async signTransaction() { return response; } }, review(tx))).rejects.toMatchObject({ code: "WALLET_MUTATION" });
  await expect(cosignPreparedTransaction(tx, { address: first.publicKey(), async signTransaction() { return { signedTxXdr: "", error: { message: "declined", code: -1 } }; } }, review(tx))).rejects.toMatchObject({ code: "WALLET_REJECTED" });
});

test("regular and fee-bump envelopes that expire during cosigning cannot complete", async () => {
  for (const sponsored of [false, true]) {
    const inner = prepared(); inner.sign(source);
    const tx = sponsored ? TransactionBuilder.buildFeeBumpTransaction(destination.publicKey(), "200", inner, networkPassphrase) : inner;
    const expires = (Number(inner.timeBounds!.maxTime) + 1) * 1000;
    const signer = keypairSigner(first); let clock: ReturnType<typeof spyOn<typeof Date, "now">> | undefined;
    try {
      await expect(cosignPreparedTransaction(tx as Transaction, { address: first.publicKey(), async signTransaction(...args) {
        const signed = await signer.signTransaction(...args); clock = spyOn(Date, "now").mockReturnValue(expires); return signed;
      } }, review(tx))).rejects.toMatchObject({ code: "INVALID_TRANSACTION" });
    } finally { clock?.mockRestore(); }
  }
});

test("pre-cancelled and full envelopes do not prompt the wallet", async () => {
  let calls = 0; const signer: FuulSigner = { address: first.publicKey(), async signTransaction() { calls++; throw new Error("must not prompt"); } };
  const tx = prepared(); const controller = new AbortController(); controller.abort();
  await expect(cosignPreparedTransaction(tx, signer, { ...review(tx), signal: controller.signal })).rejects.toMatchObject({ code: "ABORTED" });
  for (let i = 0; i < 20; i++) tx.sign(Keypair.random());
  await expect(cosignPreparedTransaction(tx, signer, review(tx))).rejects.toMatchObject({ code: "INVALID_TRANSACTION" });
  expect(calls).toBe(0);
});

import { expect, test } from "bun:test";
import { Contract, StrKey, nativeToScVal } from "@stellar/stellar-sdk";
import type { Api, Server } from "@stellar/stellar-sdk/rpc";
import type { Spec } from "@stellar/stellar-sdk/contract";
import { decodeEvent, getEventPage, watchEvents } from "../src/index.js";

const contractId = StrKey.encodeContract(Buffer.alloc(32, 8));
const event = { id: "event-1", type: "contract", contractId: new Contract(contractId), txHash: "a".repeat(64), ledger: 123, ledgerClosedAt: "2026-09-06T00:00:00Z", topic: [nativeToScVal("claimed", { type: "symbol" })], value: nativeToScVal(9007199254740993n, { type: "i128" }), inSuccessfulContractCall: true, transactionIndex: 1, operationIndex: 1 } satisfies Api.EventResponse;
const response = { events: [event], cursor: "next-cursor", latestLedger: 124, oldestLedger: 1, latestLedgerCloseTime: "1", oldestLedgerCloseTime: "0" };

test("event decoding preserves bigint values and transaction coordinates", () => {
  expect(decodeEvent(event)).toMatchObject({ contractId, ledger: 123, topics: ["claimed"], value: 9007199254740993n, hash: "a".repeat(64) });
});
test("pagination switches to a cursor without repeating ledger bounds", async () => {
  const requests: Api.GetEventsRequest[] = [];
  const rpc = { async getEvents(request: Api.GetEventsRequest) { requests.push(request); return response; } };
  const first = await getEventPage(rpc, { contractIds: [contractId], startLedger: 100 });
  await getEventPage({ getEvents: async request => { requests.push(request); return { ...response, cursor: "last-cursor", events: [] }; } }, { contractIds: [contractId], cursor: first.cursor });
  expect(requests[0]).toHaveProperty("startLedger", 100);
  expect(requests[1]).not.toHaveProperty("startLedger");
  expect(requests[1]).toHaveProperty("cursor", "next-cursor");
});
test("rejects mixed pagination modes and non-advancing pages", async () => {
  const rpc = { getEvents: async () => response };
  await expect(getEventPage(rpc, { contractIds: [contractId], startLedger: 1, cursor: "bad" } as never)).rejects.toThrow();
  await expect(getEventPage(rpc, { contractIds: [contractId], cursor: "next-cursor" })).rejects.toThrow("did not advance");
  await expect(getEventPage(rpc, { contractIds: [], startLedger: 1 })).rejects.toThrow();
  await expect(getEventPage(rpc, { contractIds: [contractId], startLedger: 2, endLedger: 1 })).rejects.toThrow();
});
test("advances past failed contract calls without exposing their events", async () => {
  const page = await getEventPage({ getEvents: async () => ({ ...response, events: [{ ...event, inSuccessfulContractCall: false }] }) }, { contractIds: [contractId], startLedger: 1 });
  expect(page.events).toEqual([]); expect(page.cursor).toBe("next-cursor");
});
test("cancels an event stream even if an RPC read hangs", async () => {
  const rpc = { getEvents: () => new Promise(() => {}) } as unknown as Server;
  const controller = new AbortController();
  const stream = watchEvents(rpc, { contractIds: [contractId], startLedger: 1 }, { signal: controller.signal });
  const pending = stream.next(); controller.abort();
  expect((await pending).done).toBe(true);
});

test("cursor validation uses the request snapshot after an RPC wait", async () => {
  const query = { contractIds: [contractId], cursor: "request-cursor" };
  const rpc = { async getEvents() {
    query.cursor = "changed-by-caller";
    return { ...response, cursor: "request-cursor" };
  } };
  await expect(getEventPage(rpc, query)).rejects.toThrow("did not advance");
});

test("event decoding retains the specification selected when the request starts", async () => {
  const selected = { parseEvent: () => ({ name: "Original", data: {} }) } as unknown as Spec;
  const replacement = { parseEvent: () => ({ name: "Replacement", data: {} }) } as unknown as Spec;
  const specs = new Map([[contractId, selected]]);
  const rpc = { async getEvents() { specs.set(contractId, replacement); return response; } };
  expect((await getEventPage(rpc, { contractIds: [contractId], startLedger: 1 }, specs)).events[0]!.parsed?.name).toBe("Original");
});

test("a stream retains its query when configuration changes before the first read", async () => {
  const query = { contractIds: [contractId], startLedger: 100 };
  const controller = new AbortController();
  let requested: Api.GetEventsRequest | undefined;
  const rpc = { async getEvents(request: Api.GetEventsRequest) { requested = request; return response; } };
  const stream = watchEvents(rpc, query, { signal: controller.signal });
  query.startLedger = 120;
  try {
    await stream.next();
    expect(requested).toHaveProperty("startLedger", 100);
  } finally { controller.abort(); await stream.return(undefined); }
});

test("an active stream retains its query and continuation cursor across consumer processing", async () => {
  const requests: Api.GetEventsRequest[] = [];
  const controller = new AbortController();
  const query = { contractIds: [contractId], startLedger: 100, limit: 1 };
  const rpc = { async getEvents(request: Api.GetEventsRequest) {
    requests.push(request);
    return { ...response, cursor: `cursor-${requests.length}` };
  } };
  const stream = watchEvents(rpc, query, { signal: controller.signal, pollIntervalMs: 1 });
  try {
    const first = await stream.next();
    query.contractIds[0] = StrKey.encodeContract(Buffer.alloc(32, 99));
    query.limit = 50;
    first.value!.cursor = "consumer-edited-cursor";
    await stream.next();
    expect(requests[0]).toHaveProperty("startLedger", 100);
    expect(requests[1]).toMatchObject({ cursor: "cursor-1", filters: [{ type: "contract", contractIds: [contractId] }], limit: 1 });
  } finally { controller.abort(); await stream.return(undefined); }
});

test("stream cancellation keeps the original signal when the options object changes", async () => {
  const controller = new AbortController();
  const replacement = new AbortController();
  const options = { signal: controller.signal, pollIntervalMs: 1 };
  const rpc = { getEvents: () => new Promise(() => {}) } as unknown as Server;
  const stream = watchEvents(rpc, { contractIds: [contractId], startLedger: 1 }, options);
  options.signal = replacement.signal;
  const pending = stream.next();
  controller.abort();
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    expect(await Promise.race([pending, new Promise(resolve => { timer = setTimeout(() => resolve("not cancelled"), 100); })])).toMatchObject({ done: true });
  } finally { clearTimeout(timer); replacement.abort(); await stream.return(undefined); }
});

test("rejects non-string input and response cursors", async () => {
  let calls = 0;
  const rpc = { async getEvents() { calls++; return response; } };
  await expect(getEventPage(rpc, { contractIds: [contractId], cursor: 123 as unknown as string })).rejects.toThrow(TypeError);
  expect(calls).toBe(0);
  await expect(getEventPage({ getEvents: async () => ({ ...response, cursor: 123 as unknown as string }) }, { contractIds: [contractId], startLedger: 1 })).rejects.toThrow("cursor");
});

import {
  parseAmount, formatAmount, keypairSigner, cosignPreparedTransaction, signPreparedTransaction,
  createFuulRpcServer, claimAuthorizations, createClaimCheck, claimReason, currencyType,
  FactoryContract, readSorobanResourceLimits,
} from "../../src/index.js";
import {
  Account, Asset, Keypair, Operation, TransactionBuilder, StrKey, xdr, Address,
  authorizeEntry, inspectAuthEntry, hash, buildAuthorizationEntryPreimage,
} from "@stellar/stellar-sdk";

function assert(value: unknown, message: string): asserts value {
  if (!value) throw new Error(message);
}

async function check() {
  assert(globalThis.Buffer === undefined, "Browser test must start without a Buffer global");
  const amount = 9007199254740993n;
  assert(parseAmount(formatAmount(amount)) === amount, "Exact amount roundtrip");
  const key = Keypair.random();
  const tx = new TransactionBuilder(new Account(key.publicKey(), "1"), {
    fee: "100", networkPassphrase: "browser consumer",
  }).addOperation(Operation.payment({
    destination: key.publicKey(), asset: Asset.native(), amount: "1",
  })).setTimeout(60).build();
  const directlySigned = await signPreparedTransaction(tx, keypairSigner(key), 1000n);
  assert(key.verify(directlySigned.hash(), directlySigned.signatures[0]!.signature.toBytes()), "Direct browser transaction signature");
  const signed = await cosignPreparedTransaction(tx, keypairSigner(key), {
    expectedSource: key.publicKey(), maxFeeStroops: 1000n,
    expectedHash: Array.from(tx.hash(), value => value.toString(16).padStart(2, "0")).join(""),
  });
  assert(key.verify(signed.hash(), signed.signatures[0]!.signature.toBytes()), "Browser cosigning signature");

  const manager = StrKey.encodeContract(new Uint8Array(32));
  const claim = createClaimCheck({
    project: manager, to: key.publicKey(), currency: manager,
    currencyType: currencyType.stellarAsset, amount, deadline: 9999999999n,
    reason: claimReason.endUserPayout, proof: new Uint8Array(32), signers: [key.publicKey()],
  });
  const root = xdr.SorobanAuthorizedInvocation.fromXdr(claimAuthorizations(manager, [claim])[0]!.invocation, "base64");
  const entry = new xdr.SorobanAuthorizationEntry({
    rootInvocation: root,
    credentials: xdr.SorobanCredentials.sorobanCredentialsAddress(new xdr.SorobanAddressCredentials({
      address: new Address(key.publicKey()).toScAddress(), nonce: 123n,
      signatureExpirationLedger: 0, signature: xdr.ScVal.scvVoid(),
    })),
  });
  const auth = await authorizeEntry(entry, key, 200, "browser consumer");
  const signatures = inspectAuthEntry(auth).signers[0]!.signatures;
  assert(signatures?.length, "Missing browser claim signature");
  assert(key.verify(hash(buildAuthorizationEntryPreimage(auth, 200, "browser consumer").toXdr()), signatures[0]!.signature),
    "Browser claim authorization signature");
  const factory = new FactoryContract.Client({
    contractId: manager, networkPassphrase: "browser consumer", rpcUrl: "https://example.invalid",
  });
  assert(factory.spec.funcResToNative("project_wasm_hash", xdr.ScVal.scvBytes(new Uint8Array(32))) instanceof Uint8Array,
    "Browser byte results");
  assert(typeof readSorobanResourceLimits === "function" && !!createFuulRpcServer("https://example.invalid").httpClient,
    "Browser RPC construction");
  assert(globalThis.Buffer === undefined, "SDK must not install a Buffer global");
  return { passed: true, checks: ["amounts", "signing", "cosigning", "claim authorization", "bindings", "RPC", "no Buffer global"] };
}

export default await check();

