      () =>
        new FuulSdk({
          rpcUrl: "https://rpc.invalid",
          networkPassphrase: Networks.TESTNET,
          contracts: {
            factory: "GAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAWHF",
            manager: contractId(2),
          },
        }),
    ).toThrow("valid Stellar contract ID");
  });
});

